pub use semio_framework_value_native_owned::*;
use semio_framework_value_ordered::OrderedSet;
use semio_framework_value_testing_allocator::observe_retirement_allocations as heap;
pub use semio_framework_value_testing_admission as source_fixture;
use source_fixture::{Wallet,receive,post_step,denials,close_owned};
const BODY:usize=32768;
#[test]fn original_set_receiving_matches_fixture_admits_every_insert_and_closes_every_partial_owner(){let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📐️.json")).unwrap();for case in law["cases"].as_array().unwrap(){for cut in law["cancelCuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain(std::iter::once(100000)){let mut bank=Wallet::from_profile(&law["stock"]);let s=source_fixture::capture(DslValue::Array(case["members"].as_array().unwrap().iter().map(|m|DslValue::String(m.as_str().unwrap().into())).collect()),&mut bank,|w|w.loan(1,BODY),|w|w.work_remaining(),|w,p,work,h,g|w.post(p,work,g,h));let(mut r,h)=heap(<OrderedSet as NativeReceive<DslValue>>::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut c=NativeDecodeControl::new(1<<26,&mut callback);for turn in 0..cut{if r.output_ready(){break}let d=r.demands(s.borrow(),BODY,bank.work_remaining()).unwrap();assert!(d.copy_bytes<=BODY,"original set header exceeds native policy: {d:?}");let g=bank.loan(1,BODY);for denied in denials(g,d){let(t,h)=heap(||receive(&mut c,denied,bank.work_loan(bank.work_remaining()),|c|{let maximum=c.available_work_units().unwrap();r.advance(s.borrow(),c,BODY,maximum,denied)}));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.demands(s.borrow(),BODY,bank.work_remaining()).unwrap(),d)}let(t,h)=heap(||receive(&mut c,g,bank.work_loan(bank.work_remaining()),|c|{let maximum=c.available_work_units().unwrap();r.advance(s.borrow(),c,BODY,maximum,g)}));assert!(t.result.as_ref().unwrap().progress().fits(g),"actual set receipt exceeds {g:?} on turn {turn}");post_step(&mut bank,t,g,h,OriginalReceivingPrimary::retained_progress).unwrap();}if r.output_ready(){let g=bank.loan(1,BODY);let(t,h)=heap(||r.take(g));let(set,p)=t.result.unwrap().unwrap();bank.post(p,t.work,g,h);let members:Vec<_>=set.iter().map(|m|serde_json::json!(m)).collect();assert_eq!(serde_json::Value::Array(members),case["expected"]);let oracle:std::collections::BTreeSet<&str>=case["members"].as_array().unwrap().iter().map(|m|m.as_str().unwrap()).collect();assert!(set.iter().map(String::as_str).eq(oracle.into_iter()));close_owned(set,&mut bank,BODY,100000)}else{assert_ne!(cut,100000,"actual set preparation stalled")}let g=bank.loan(1,BODY);let q=r.begin_close_work_demand().unwrap();assert!(q<=bank.work_remaining());let(t,h)=heap(||r.begin_close_step(g,q));post_step(&mut bank,t,g,h,|e|panic!("unexpected close-intent refusal: {e:?}")).unwrap();let mut actual=None;for _ in 0..100000{if r.terminal_is_empty()&&actual.is_none(){break}let d=crate::source_fixture::close_demands(&actual,r.close_demands(BODY)).unwrap();let g=bank.loan(1,BODY);for denied in denials(g,d){let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,denied,bank.work_remaining(),r.close_demands(4096),r.close_work_demand(4096),|g,a|r.close_step(g,a)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(crate::source_fixture::close_demands(&actual,r.close_demands(BODY)).unwrap(),d)}let(t,h)=heap(||crate::source_fixture::close_step(&mut actual,g,bank.work_remaining(),r.close_demands(4096),r.close_work_demand(4096),|g,a|r.close_step(g,a)));post_step(&mut bank,t,g,h,|e|e.retained_progress()).unwrap();}assert!(r.terminal_is_empty());close_owned(s,&mut bank,BODY,100000);}}}
